/* AppAdminDashboardMapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD  = #{userCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.USE_YN   = 'Y'

/* AppAdminDashboardMapper.selectAttdCounts */ SELECT ( SELECT COUNT(DISTINCT A.USER_CD) FROM TB_USER_ATTD_MGMT A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND A.WORK_YMD = #{todayYmd} AND A.DEL_YN = 'N' AND A.CHECK_IN_TIME IS NOT NULL
AND A.NODE_CD
) AS checkedInCnt , ( SELECT COUNT(DISTINCT P.USER_CD) FROM TB_USER_WORK_PLAN P INNER JOIN TB_USER U ON U.CMPNY_CD = P.CMPNY_CD AND U.SITE_CD = P.SITE_CD AND U.USER_CD = P.USER_CD AND U.USE_YN = 'Y' INNER JOIN TB_SCH_MGMT S ON S.CMPNY_CD = P.CMPNY_CD AND S.SITE_CD = P.SITE_CD AND S.SCH_CD = P.WORK_PLAN_CD AND S.USE_YN = 'Y'
WHERE P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.WORK_YMD = #{todayYmd}
AND U.NODE_CD
) AS scheduledCnt , ( SELECT COUNT(DISTINCT L.USER_CD) FROM TB_USER_LEAVE_USE L INNER JOIN TB_USER U ON U.CMPNY_CD = L.CMPNY_CD AND U.SITE_CD = L.SITE_CD AND U.USER_CD = L.USER_CD AND U.USE_YN = 'Y' WHERE L.CMPNY_CD = #{cmpnyCd} AND L.SITE_CD = #{siteCd} AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.USE_UNIT_TYPE = '00' AND L.START_DATE <= #{todayYmd} AND L.END_DATE >= #{todayYmd}
AND U.NODE_CD
) AS leaveCnt

/* AppAdminDashboardMapper.selectPatrolCount */
SELECT
    (
        SELECT COUNT(DISTINCT T.CHKPT_CD)
        FROM TB_CHKPT_TYPE_MGMT T
        WHERE T.CMPNY_CD = #{cmpnyCd}
          AND T.SITE_CD  = #{siteCd}
          AND T.USE_YN   = 'Y'
    )                                                                       AS targetCnt
  , (
        SELECT COUNT(DISTINCT D.CHKPT_CD)
        FROM TB_CHKPT_INSPECT_ANSWER D
             INNER JOIN TB_CHKPT_TYPE_MGMT T
                ON  T.CMPNY_CD = D.CMPNY_CD
                AND T.SITE_CD  = D.SITE_CD
                AND T.CHKPT_CD = D.CHKPT_CD
                AND T.USE_YN   = 'Y'
        WHERE D.CMPNY_CD  = #{cmpnyCd}
          AND D.SITE_CD   = #{siteCd}
          AND D.WORK_DATE = #{todayYmd}
    )                                                                       AS completedCnt

/* AppAdminDashboardMapper.selectRiskPendingCount */
SELECT
    COUNT(1)
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.ASSESSMENT_STATUS = '001'

/* AppAdminDashboardMapper.selectNearMissNewCount */
SELECT
    COUNT(1)
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.USE_YN   = 'Y'
  AND A.REPORT_STATUS_CD = '100'
